CREATE TABLE IF NOT EXISTS gis_phase340_geometry_evidence (id UUID PRIMARY KEY DEFAULT gen_random_uuid(), crosswalk_version TEXT NOT NULL, candidate_id UUID NOT NULL, source_feature_id UUID NOT NULL, target_feature_id UUID NOT NULL, source_geometry_type TEXT, target_geometry_type TEXT, source_area DOUBLE PRECISION, target_area DOUBLE PRECISION, intersection_area DOUBLE PRECISION, source_overlap_ratio DOUBLE PRECISION, target_overlap_ratio DOUBLE PRECISION, iou DOUBLE PRECISION, geometry_valid BOOLEAN NOT NULL DEFAULT false, method TEXT NOT NULL, evidence JSONB NOT NULL DEFAULT '{}'::jsonb, created_at TIMESTAMPTZ NOT NULL DEFAULT now(), UNIQUE(crosswalk_version,candidate_id));